<?php
namespace Tests\Feature;
use App\Models\{AttendanceRecord,ClassSchedule,ClassSession,Course,CourseEnrollment,Department,Program,Role,Room,Section,Semester,Student,Teacher,User};
use App\Services\AttendanceService;
use Carbon\Carbon;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Validation\ValidationException;
use Tests\TestCase;

class AttendanceEngineTest extends TestCase
{
 use RefreshDatabase;
 protected function setUp():void{parent::setUp();$this->seed();}
 private function fixture():array{$d=Department::create(['name'=>'Science','code'=>'SCI'.uniqid(),'status'=>'active']);$p=Program::create(['department_id'=>$d->id,'name'=>'Computing','code'=>'CMP'.uniqid(),'duration_years'=>4,'status'=>'active']);$sem=Semester::create(['name'=>'Fall','number'=>1,'academic_year'=>'2026-2027','status'=>'active']);$sec=Section::create(['program_id'=>$p->id,'semester_id'=>$sem->id,'name'=>'A','code'=>'SEC'.uniqid(),'status'=>'active']);$course=Course::create(['department_id'=>$d->id,'course_code'=>'ATT'.uniqid(),'name'=>'Attendance','credit_hours'=>3,'status'=>'active']);$teacherUser=User::factory()->create(['role_id'=>Role::where('name','teacher')->value('id')]);$teacher=Teacher::create(['user_id'=>$teacherUser->id,'employee_id'=>'TEA'.uniqid(),'department_id'=>$d->id,'official_email'=>$teacherUser->email,'status'=>'active']);$room=Room::create(['name'=>'Lab '.uniqid(),'building'=>'B','capacity'=>30,'status'=>'active']);$schedule=ClassSchedule::create(['course_id'=>$course->id,'teacher_id'=>$teacher->id,'section_id'=>$sec->id,'room_id'=>$room->id,'day_of_week'=>1,'start_time'=>'09:00','end_time'=>'10:00','grace_period_minutes'=>20,'status'=>'active','academic_year'=>'2026-2027','semester_id'=>$sem->id]);$session=ClassSession::create(['schedule_id'=>$schedule->id,'course_id'=>$course->id,'teacher_id'=>$teacher->id,'section_id'=>$sec->id,'room_id'=>$room->id,'session_date'=>'2026-01-05','scheduled_start_at'=>'2026-01-05 09:00:00','scheduled_end_at'=>'2026-01-05 10:00:00','attendance_open_at'=>'2026-01-05 09:00:00','attendance_close_at'=>'2026-01-05 10:00:00','status'=>'open']);$studentUser=User::factory()->create(['role_id'=>Role::where('name','student')->value('id')]);$student=Student::create(['user_id'=>$studentUser->id,'student_id'=>'STU'.uniqid(),'department_id'=>$d->id,'program_id'=>$p->id,'semester_id'=>$sem->id,'section_id'=>$sec->id,'official_email'=>$studentUser->email,'status'=>'active']);CourseEnrollment::create(['student_id'=>$student->id,'course_id'=>$course->id,'section_id'=>$sec->id,'academic_year'=>'2026-2027','semester_id'=>$sem->id,'status'=>'active']);return compact('session','student','teacherUser','course','sec','sem');}
 public function test_mark_at_start_is_present():void{$f=$this->fixture();Carbon::setTestNow('2026-01-05 09:00:00');$record=app(AttendanceService::class)->mark($f['session'],$f['student']->id,$f['teacherUser']);$this->assertSame('present',$record->status);Carbon::setTestNow();}
 public function test_mark_exactly_at_grace_boundary_is_late():void{$f=$this->fixture();Carbon::setTestNow('2026-01-05 09:20:00');$record=app(AttendanceService::class)->mark($f['session'],$f['student']->id,$f['teacherUser']);$this->assertSame('late',$record->status);Carbon::setTestNow();}
 public function test_duplicate_marking_does_not_overwrite():void{$f=$this->fixture();Carbon::setTestNow('2026-01-05 09:00:00');$service=app(AttendanceService::class);$service->mark($f['session'],$f['student']->id,$f['teacherUser']);$this->expectException(ValidationException::class);$service->mark($f['session'],$f['student']->id,$f['teacherUser']);Carbon::setTestNow();}
 public function test_finalization_marks_only_eligible_students_absent_and_is_idempotent():void{$f=$this->fixture();$admin=User::factory()->create(['role_id'=>Role::where('name','admin')->value('id')]);Carbon::setTestNow('2026-01-05 10:01:00');$result=app(AttendanceService::class)->finalize($f['session'],$admin);$this->assertSame(1,$result['absent_created']);$this->assertSame(1,AttendanceRecord::where('status','absent')->count());$this->assertSame('closed',$f['session']->fresh()->status);Carbon::setTestNow();}
 public function test_teacher_cannot_mark_another_teachers_session():void{$f=$this->fixture();$other=User::factory()->create(['role_id'=>Role::where('name','teacher')->value('id')]);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);app(AttendanceService::class)->mark($f['session'],$f['student']->id,$other);}
}
